  return mesh;
}

// Pillowy cushion with button tufting on its +Y face
function makeCushion(name, w, h, d, opts = {}) {
  const {
    bulge = 0.018,
    tufts = [],
    tuftDepth = 0.012,
    tuftRadius = 0.035
  } = opts;
  const hw = w / 2, hh = h / 2, hd = d / 2;

  const displace = (x, y, z, out) => {
    const nx = x / hw, ny = y / hh, nz = z / hd;
    const ax = Math.abs(nx), ay = Math.abs(ny), az = Math.abs(nz);
    const sx = Math.pow(ax, 6), sz = Math.pow(az, 6);
    const edgeY = ay * ay * ay;
    let X = x, Y = y, Z = z;

    // soften top/bottom perimeter edges
    X -= Math.sign(x) * hh * 0.5 * edgeY * sx;
    Z -= Math.sign(z) * hh * 0.5 * edgeY * sz;

    // round corners in plan
    const corner = sx * sz;
    X -= Math.sign(x) * hh * 0.4 * corner;
    Z -= Math.sign(z) * hh * 0.4 * corner;

    // puffy faces (bottom puffs less)
    const fx = 1 - nx * nx, fz = 1 - nz * nz;
    Y += ny * bulge * fx * fz * (ny > 0 ? 1 : 0.35);

    // gently bulging side walls
    const side = 1 - ny * ny;
    X += Math.sign(x) * hh * 0.16 * side * Math.pow(ax, 4) * (1 - Math.pow(az, 8));
    Z += Math.sign(z) * hh * 0.16 * side * Math.pow(az, 4) * (1 - Math.pow(ax, 8));

    // button tufting dimples
    if (ny > 0 && tufts.length) {
      let s = 0;
      for (const [u, v] of tufts) {
        const dx = x - u * hw, dz = z - v * hd;
        s += Math.exp(-(dx * dx + dz * dz) / (tuftRadius * tuftRadius));
      }
      Y -= tuftDepth * Math.min(s, 1.2) * ny;
    }
    out.set(X, Y, Z);
  };

  let geo = new THREE.BoxGeometry(w, h, d, 64, 8, 64);
  const pos = geo.attributes.position;
  const v = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    displace(pos.getX(i), pos.getY(i), pos.getZ(i), v);
    pos.setXYZ(i, v.x, v.y, v.z);
  }
  geo.deleteAttribute('normal');
  geo.deleteAttribute('uv');
  geo = mergeVertices(geo, 1e-5);
  geo.computeVertexNormals();

  const group = new THREE.Group();
  group.name = name;

  const body = new THREE.Mesh(geo, fabricMat);
  body.name = `${name} Body`;
  group.add(body);

  if (tufts.length) {
    const buttons = new THREE.Group();
    buttons.name = `${name} Buttons`;
    const btnGeo = new THREE.SphereGeometry(0.011, 18, 12);
    tufts.forEach(([u, vv], i) => {
      const p = new THREE.Vector3();
      displace(u * hw, hh, vv * hd, p);
      const b = new THREE.Mesh(btnGeo, buttonMat);
      b.name = `Button ${i + 1}`;
      b.scale.set(1, 0.45, 1);
      b.position.set(p.x, p.y - 0.001, p.z);
      buttons.add(b);
    });
    group.add(buttons);
  }
  return group;
}

